mapper.select:
select item_quantity
  from tbl_inventory
 where user_id = #{userId}
   and item_code = #{itemCode}

mapper.update:
update tbl_inventory
   set item_quantity = item_quantity - #{quantity}
 where user_id = #{userId}
   and item_code = #{itemCode}
   and item_quantity >= #{quantity}

mapper.delete:
delete from tbl_inventory
 where user_id = #{userId}
   and item_code = #{itemCode}
